30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.advice.CityCapacityExceededException;
34	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
35	import org.springframework.samples.petclinic.rest.advice.DuplicateEmailException;
36	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
37	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.samples.petclinic.util.AddressNormalizer;
47	import org.springframework.samples.petclinic.util.HouseholdNormalizer;
48	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /** Maximum number of owners a single city may contain; creating an owner in a city that
67	     *  already has this many owners is rejected with 409 Conflict. */
68	    private static final int MAX_OWNERS_PER_CITY = 50;
69	
70	    /** Maximum number of owners that may be created on a single day (by registration date); creating
71	     *  an owner once this many owners already carry today's registration date is rejected with
72	     *  429 Too Many Requests. */
73	    private static final int MAX_OWNERS_PER_DAY = 100;
74	
75	    /** When more than this many owners already carry today's registration date at creation time, the
76	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
77	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
78	
79	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
80	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
81	
82	    private final ClinicService clinicService;
83	
84	    private final OwnerMapper ownerMapper;
85	
86	    private final PetMapper petMapper;
87	
88	    private final VisitMapper visitMapper;
89	
90	    private final TelephoneNormalizer telephoneNormalizer;
91	
92	    private final HouseholdNormalizer householdNormalizer;
93	
94	    private final AddressNormalizer addressNormalizer;
95	
96	    public OwnerRestControllerV1(ClinicService clinicService,
97	                                 OwnerMapper ownerMapper,
98	                                 PetMapper petMapper,
99	                                 VisitMapper visitMapper,
100	                                 TelephoneNormalizer telephoneNormalizer,
101	                                 HouseholdNormalizer householdNormalizer,
102	                                 AddressNormalizer addressNormalizer) {
103	        this.clinicService = clinicService;
104	        this.ownerMapper = ownerMapper;
105	        this.petMapper = petMapper;
106	        this.visitMapper = visitMapper;
107	        this.telephoneNormalizer = telephoneNormalizer;
108	        this.householdNormalizer = householdNormalizer;
109	        this.addressNormalizer = addressNormalizer;
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
115	        Collection<Owner> owners;
116	        if (lastName != null) {
117	            owners = this.clinicService.findOwnerByLastName(lastName);
118	        } else {
119	            owners = this.clinicService.findAllOwners();
120	        }
121	        if (owners.isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
130	        Owner owner = this.clinicService.findOwnerById(ownerId);
131	        if (owner == null) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
140	        HttpHeaders headers = new HttpHeaders();
141	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
142	        normalizeOwnerFields(owner);
143	        // Enforce the pre-persistence policies that can reject the new owner outright.
144	        rejectDisallowedOwnerCreation(owner);
145	        // Resolve the owner's household membership: reject an un-opted-in duplicate household,
146	        // assign the shared 'householdId' when the request opts in, and record the household size.
147	        applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
148	        // Assign the remaining create-time derived fields (namesake count, customer code,
149	        // membership number and bulk-signup warning), each fixed at creation time.
150	        assignDerivedFields(owner);
151	        this.clinicService.saveOwner(owner);
152	        // Emit an audit line for the successful create, carrying the owner id, customer code and
153	        // registration date so the create can be traced from the dedicated AUDIT log.
154	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
155	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
156	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
157	        headers.setLocation(UriComponentsBuilder.newInstance()
158	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
159	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
160	    }
161	
162	    /**
163	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
164	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
165	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
166	     * the sequence of create-time rejections stays readable and a new rule is added as one more
167	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
168	     * and persistence steps. The household rule lives in {@link #applyHouseholdMembership} rather
169	     * than here because it shares the matched-member lookup with the shared household-id assignment.
170	     *
171	     * @param owner the newly mapped and normalized owner being created
172	     */
173	    private void rejectDisallowedOwnerCreation(Owner owner) {
174	        rejectWhenDailyLimitReached(owner);
175	        rejectWhenCityAtCapacity(owner);
176	        rejectWhenTelephoneInUse(owner);
177	        rejectWhenEmailInUse(owner);
178	    }
179	
180	    /**
181	     * Applies the household-membership rules for a newly normalized owner being created. It finds
182	     * the existing owners who share the owner's household (same last name and address, compared
183	     * case-insensitively with collapsed whitespace), then, using that single lookup: rejects the
184	     * create with a 409 Conflict when the owner would join an existing household without opting in
185	     * via {@code sharesHousehold}; otherwise, when opting in and joining an existing household,
186	     * assigns the new owner and every existing member the same stable {@code householdId}; and
187	     * finally records the owner's {@code householdSize}. These steps live together here, out of the
188	     * {@link #rejectDisallowedOwnerCreation} pipeline, precisely because they share that one
189	     * matched-member lookup.
190	     *
191	     * @param owner           the newly mapped and normalized owner being created
192	     * @param sharesHousehold whether the request opted in to joining an existing household
193	     */
194	    private void applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
195	        // Identify any existing owners who share a household (same last name and address,
196	        // compared case-insensitively with collapsed whitespace) with the owner being created.
197	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
198	        // Reject creating an owner who shares a household with an existing owner, unless the
199	        // request explicitly opts in with 'sharesHousehold' true.
200	        if (!sharesHousehold && !householdMembers.isEmpty()) {
201	            throw new DuplicateHouseholdException(
202	                "An owner with the same last name and address already exists");
203	        }
204	        // When opting in and joining an existing household, assign the new owner and every
205	        // existing member the same stable household identifier derived from the last name and
206	        // address, so all owners of the household share one 'householdId'.
207	        if (sharesHousehold && !householdMembers.isEmpty()) {
208	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
209	            owner.setHouseholdId(householdId);
210	            for (Owner member : householdMembers) {
211	                if (!householdId.equals(member.getHouseholdId())) {
212	                    member.setHouseholdId(householdId);
213	                    this.clinicService.saveOwner(member);
214	                }
215	            }
216	        }
217	        // Record the size of this owner's household after this create, i.e. the number of owners
218	        // sharing this owner's 'householdId' once it is persisted. An owner that shares an existing
219	        // household counts the matched members plus itself; an owner without a shared household is a
220	        // household of one. Fixed at creation time.
221	        owner.setHouseholdSize(owner.getHouseholdId() == null ? 1 : householdMembers.size() + 1);
222	    }
223	
224	    /**
225	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
226	     * has already been resolved: the namesake count, the per-city customer code, the membership
227	     * number derived from that customer code and the registration year, and the bulk-signup warning
228	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
229	     * here keeps {@link #addOwner} focused on the high-level create sequence.
230	     *
231	     * @param owner the owner being created, already normalized and with its household resolved
232	     */
233	    private void assignDerivedFields(Owner owner) {
234	        // Record how many existing owners already share this owner's first and last name
235	        // (compared case-insensitively) before this create, fixed at creation time.
236	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
237	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' from the city, last name and a
238	        // per-city sequence equal to one more than the owners already in that city, fixed at
239	        // creation time.
240	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
241	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
242	        // of the registration date's year (e.g. 'LON-SMI-0007-M26'), fixed at creation time.
243	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
244	        // Flag the create when more than 80 owners have already been created on this owner's
245	        // (adjusted business-day) registration date, fixed at creation time.
246	        owner.setBulkSignupWarning(
247	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
248	    }
249	
250	    /**
251	     * Rejects creating an owner whose lower-cased email is already used by another owner, with
252	     * 409 Conflict.
253	     *
254	     * @param owner the owner being created
255	     */
256	    private void rejectWhenEmailInUse(Owner owner) {
257	        String normalizedEmail = owner.getEmail();
258	        if (isValueInUseByExistingOwner(Owner::getEmail, this::normalizeEmail, normalizedEmail)) {
259	            throw new DuplicateEmailException(
260	                "An owner with email " + normalizedEmail + " already exists");
261	        }
262	    }
263	
264	    /**
265	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
266	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
267	     *
268	     * @param owner the owner being created
269	     */
270	    private void rejectWhenDailyLimitReached(Owner owner) {
271	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
272	            throw new DailyOwnerLimitExceededException(
273	                "The maximum number of owners that may be created today has already been reached");
274	        }
275	    }
276	
277	    /**
278	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
279	     * or more owners, with 409 Conflict.
280	     *
281	     * @param owner the owner being created
282	     */
283	    private void rejectWhenCityAtCapacity(Owner owner) {
284	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
285	            throw new CityCapacityExceededException(
286	                "The city " + owner.getCity() + " already contains the maximum number of owners");
287	        }
288	    }
289	
290	    /**
291	     * Rejects creating an owner whose normalized telephone is already used by another owner, with
292	     * 409 Conflict.
293	     *
294	     * @param owner the owner being created
295	     */
296	    private void rejectWhenTelephoneInUse(Owner owner) {
297	        String normalizedTelephone = owner.getTelephone();
298	        if (isTelephoneInUse(normalizedTelephone)) {
299	            throw new DuplicateTelephoneException(
300	                "An owner with telephone " + normalizedTelephone + " already exists");
301	        }
302	    }
303	
304	    /**
305	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
306	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
307	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
308	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
309	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
310	     * server's current date. Canonicalising the address here, before the household checks read it,
311	     * ensures duplicate detection and the shared household id both compare the normalized form.
312	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
313	     * duplicate, household and customer-code rules.
314	     *
315	     * @param owner the newly mapped owner to canonicalize
316	     */
317	    private void normalizeOwnerFields(Owner owner) {
318	        // Normalize the address on create so it is stored and returned in canonical form and every
319	        // later comparison (household duplicate detection and the shared household id) uses it.
320	        // A value that is blank after normalization is rejected with 400.
321	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
322	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
323	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
324	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
325	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
326	        // Store the (already syntactically validated) email lower-cased so it is persisted and
327	        // returned in canonical form. A missing email is left untouched.
328	        owner.setEmail(normalizeEmail(owner.getEmail()));
329	        // Default the registration date to the server's current date when the client did not
330	        // supply one, then roll the effective date forward to a business day so a Saturday or
331	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
332	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
333	        // date-derived field (such as the membership number's year segment) and the per-day
334	        // create-limit are computed from.
335	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
336	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
337	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
338	    }
339	
340	    /**
341	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
342	     * following Monday, while a weekday is returned unchanged. Applied to the effective
343	     * registration date (whether supplied in the request or defaulted to the server date) so the
344	     * persisted registration date, every value derived from it and the per-day create-limit all
345	     * use the adjusted business day.
346	     *
347	     * @param date the effective registration date
348	     * @return the same date if it is a weekday, otherwise the following Monday
349	     */
350	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
351	        java.time.LocalDate adjusted = date;
352	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
353	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
354	            adjusted = adjusted.plusDays(1);
355	        }
356	        return adjusted;
357	    }
358	
359	    /**
360	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
361	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
362	     * syntactically valid address (rejecting anything else with 400).
363	     *
364	     * @param email the email value (may be {@code null})
365	     * @return the lower-cased email, or {@code null} if the input was {@code null}
366	     */
367	    private String normalizeEmail(String email) {
368	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
369	    }
370	
371	    /**
372	     * Builds the customer code '<CITY3>-<LAST3>-<NNNN>' for a newly created owner, where CITY3 is
373	     * the upper-cased first three letters of the city, LAST3 is the upper-cased first three letters
374	     * of the last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than
375	     * the owners already in that city (e.g. 'LON-SMI-0007').
376	     *
377	     * @param city     the owner's city
378	     * @param lastName the owner's last name
379	     * @return the formatted customer code
380	     */
381	    private String nextCustomerCode(String city, String lastName) {
382	        String cityPrefix = city.substring(0, Math.min(3, city.length()))
383	            .toUpperCase(java.util.Locale.ROOT);
384	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length()))
385	            .toUpperCase(java.util.Locale.ROOT);
386	        int sequence = countOwnersInCity(city) + 1;
387	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
388	    }
389	
390	    /**
391	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
392	     * fix the per-city sequence of an owner's customer code at creation time.
393	     *
394	     * @param city the city of the owner being created
395	     * @return the number of existing owners in a matching city
396	     */
397	    private int countOwnersInCity(String city) {
398	        return (int) this.clinicService.findAllOwners().stream()
399	            .filter(existing -> existing.getCity() != null
400	                && existing.getCity().equalsIgnoreCase(city))
401	            .count();
402	    }
403	
404	    /**
405	     * Counts the existing owners whose registration date is the given adjusted business day. Used
406	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
407	     * owners already carry that business day as their registration date.
408	     *
409	     * @param date the adjusted business-day registration date to match
410	     * @return the number of existing owners registered on that date
411	     */
412	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
413	        return (int) this.clinicService.findAllOwners().stream()
414	            .filter(existing -> date.equals(existing.getRegistrationDate()))
415	            .count();
416	    }
417	
418	    /**
419	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
420	     * the last two digits of the registration date's year (e.g. 'LON-SMI-0007-M26').
421	     *
422	     * @param customerCode     the owner's customer code
423	     * @param registrationDate the owner's registration date
424	     * @return the formatted membership number
425	     */
426	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
427	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
428	    }
429	
430	    /**
431	     * Determines whether the given normalized telephone is already used by an existing owner.
432	     * Stored telephones are normalized to E.164 before comparison so values that differ only in
433	     * formatting (spaces, dashes, brackets) or in national vs. international notation are treated
434	     * as the same number.
435	     *
436	     * @param normalizedTelephone the normalized (E.164) telephone to look for
437	     * @return {@code true} if another owner already uses this telephone
438	     */
439	    private boolean isTelephoneInUse(String normalizedTelephone) {
440	        return isValueInUseByExistingOwner(Owner::getTelephone, telephoneNormalizer::normalize,
441	            normalizedTelephone);
442	    }
443	
444	    /**
445	     * Determines whether the given already-normalized value is used by an existing owner for the
446	     * field read by {@code accessor}, comparing each existing owner's value in the same normalized
447	     * form produced by {@code normalizer}. Shared by the create-time uniqueness rules so each rule
448	     * only supplies the field to read and how to normalize it.
449	     *
450	     * @param accessor        reads the field to compare from an existing owner
451	     * @param normalizer      canonicalizes an existing owner's value into the same form as
452	     *                        {@code normalizedValue}
453	     * @param normalizedValue the already-normalized value to look for
454	     * @return {@code true} if an existing owner already uses this value
455	     */
456	    private boolean isValueInUseByExistingOwner(java.util.function.Function<Owner, String> accessor,
457	                                                java.util.function.UnaryOperator<String> normalizer,
458	                                                String normalizedValue) {
459	        if (normalizedValue == null) {
460	            return false;
461	        }
462	        return this.clinicService.findAllOwners().stream()
463	            .map(accessor)
464	            .map(normalizer)
465	            .anyMatch(normalizedValue::equals);
466	    }
467	
468	    /**
469	     * Returns the existing owners who share the given household, i.e. have the same last name and
470	     * the same address. The comparison delegates to {@link HouseholdNormalizer} so that values
471	     * differing only in letter case or in incidental whitespace are treated as the same household.
472	     *
473	     * @param lastName the last name of the owner being created
474	     * @param address  the address of the owner being created
475	     * @return the existing owners with a matching last name and address (possibly empty)
476	     */
477	    private List<Owner> sameHouseholdOwners(String lastName, String address) {
478	        String householdKey = householdNormalizer.householdKey(lastName, address);
479	        return this.clinicService.findAllOwners().stream()
480	            .filter(existing -> householdNormalizer
481	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey))
482	            .toList();
483	    }
484	
485	    /**
486	     * Counts the existing owners who share the given first and last name, compared
487	     * case-insensitively. Used to fix an owner's namesake count at creation time.
488	     *
489	     * @param firstName the first name of the owner being created
490	     * @param lastName  the last name of the owner being created
491	     * @return the number of existing owners with a matching first and last name
492	     */
493	    private int countNamesakes(String firstName, String lastName) {
494	        return (int) this.clinicService.findAllOwners().stream()
495	            .filter(existing -> existing.getFirstName() != null
496	                && existing.getFirstName().equalsIgnoreCase(firstName)
497	                && existing.getLastName() != null
498	                && existing.getLastName().equalsIgnoreCase(lastName))
499	            .count();
500	    }
501	
502	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
503	    @Override
504	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
505	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
506	        if (currentOwner == null) {
507	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
508	        }
509	        currentOwner.setAddress(ownerFieldsDto.getAddress());
510	        currentOwner.setCity(ownerFieldsDto.getCity());
511	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
512	        currentOwner.setLastName(ownerFieldsDto.getLastName());
513	        // Normalize the telephone to canonical E.164 form so it is stored and returned
514	        // consistently with create; an unformattable value is rejected with 400.
515	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
516	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
517	        this.clinicService.saveOwner(currentOwner);
518	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
519	    }
520	
521	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
522	    @Transactional
523	    @Override
524	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
525	        Owner owner = this.clinicService.findOwnerById(ownerId);
526	        if (owner == null) {
527	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
528	        }
529	        this.clinicService.deleteOwner(owner);
530	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
531	    }
532	
533	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
534	    @Override
535	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
536	        Owner owner = this.clinicService.findOwnerById(ownerId);
537	        if (owner == null) {
538	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
539	        }
540	        HttpHeaders headers = new HttpHeaders();
541	        Pet pet = petMapper.toPet(petFieldsDto);
542	        owner.setId(ownerId);
543	        pet.setOwner(owner);
544	        pet.getType().setName(null);
545	        this.clinicService.savePet(pet);
546	        PetDto petDto = petMapper.toPetDto(pet);
547	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
548	            .buildAndExpand(pet.getId()).toUri());
549	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
550	    }
551	
552	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
553	    @Override
554	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
555	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
556	        if (currentOwner != null) {
557	            Pet currentPet = this.clinicService.findPetById(petId);
558	            if (currentPet != null) {
559	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
560	                currentPet.setName(petFieldsDto.getName());
561	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
562	                this.clinicService.savePet(currentPet);
563	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
564	            }
565	        }
566	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
567	    }
568	
569	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
570	    @Override
571	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
572	        HttpHeaders headers = new HttpHeaders();
573	        Visit visit = visitMapper.toVisit(visitFieldsDto);
574	        Pet pet = new Pet();
575	        pet.setId(petId);
576	        visit.setPet(pet);
577	        this.clinicService.saveVisit(visit);
578	        VisitDto visitDto = visitMapper.toVisitDto(visit);
579	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
580	            .buildAndExpand(visit.getId()).toUri());
581	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
582	    }
583	
584	
585	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
586	    @Override
587	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
588	        Owner owner = this.clinicService.findOwnerById(ownerId);
589	        if (owner != null) {
590	            Pet pet = owner.getPet(petId);
591	            if (pet != null) {
592	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
593	            }
594	        }
595	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
596	    }
597	}
